#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define MAX_PACKET_SIZE 4096
#define MAX_FIELD_COUNT 64
#define HEADER_MAGIC 0xCAFEBABE
#define PROTOCOL_VERSION 3

typedef struct {
    uint32_t magic;
    uint8_t version;
    uint8_t flags;
    uint16_t field_count;
    uint32_t total_length;
    uint32_t checksum;
} __attribute__((packed)) packet_header_t;

typedef struct {
    uint16_t field_type;
    int16_t field_length;  /* signed: protocol spec says -1 means 'use default' */
    uint8_t field_flags;
    uint8_t reserved[3];
} __attribute__((packed)) field_descriptor_t;

typedef struct {
    char *data;
    size_t capacity;
    size_t used;
} output_buffer_t;

static uint32_t compute_checksum(const uint8_t *data, size_t len) {
    uint32_t sum = 0;
    for (size_t i = 0; i < len; i++) {
        sum = ((sum << 5) + sum) + data[i];
    }
    return sum;
}

static int validate_header(const packet_header_t *hdr) {
    if (ntohl(hdr->magic) != HEADER_MAGIC) {
        fprintf(stderr, "Invalid magic: 0x%08x\n", ntohl(hdr->magic));
        return -1;
    }
    if (hdr->version != PROTOCOL_VERSION) {
        fprintf(stderr, "Unsupported version: %d\n", hdr->version);
        return -1;
    }
    if (ntohs(hdr->field_count) > MAX_FIELD_COUNT) {
        fprintf(stderr, "Too many fields: %d\n", ntohs(hdr->field_count));
        return -1;
    }
    if (ntohl(hdr->total_length) > MAX_PACKET_SIZE) {
        fprintf(stderr, "Packet too large: %u\n", ntohl(hdr->total_length));
        return -1;
    }
    return 0;
}

static int validate_field_type(uint16_t ftype) {
    /* Only allow known field types */
    switch (ftype) {
        case 0x0001: /* string */
        case 0x0002: /* integer */
        case 0x0003: /* binary blob */
        case 0x0004: /* nested message */
        case 0x0005: /* array */
            return 1;
        default:
            return 0;
    }
}

static output_buffer_t *create_output_buffer(size_t initial_cap) {
    output_buffer_t *buf = calloc(1, sizeof(output_buffer_t));
    if (!buf) return NULL;
    buf->data = malloc(initial_cap);
    if (!buf->data) { free(buf); return NULL; }
    buf->capacity = initial_cap;
    buf->used = 0;
    return buf;
}

static void free_output_buffer(output_buffer_t *buf) {
    if (buf) {
        free(buf->data);
        free(buf);
    }
}

/*
 * Process a single field from the packet.
 * field_length is signed per protocol spec:
 *   -1 means use type-specific default length
 *   0 means empty field (valid)
 *   >0 means explicit length
 * We validate that field_length < MAX_PACKET_SIZE to prevent oversized fields.
 */
static int process_field(output_buffer_t *out, const field_descriptor_t *desc,
                         const uint8_t *field_data, size_t remaining) {
    int16_t field_length = (int16_t)ntohs(desc->field_length);
    uint16_t field_type = ntohs(desc->field_type);

    if (!validate_field_type(field_type)) {
        fprintf(stderr, "Unknown field type: 0x%04x\n", field_type);
        return -1;
    }

    /* Handle default length sentinel */
    if (field_length == -1) {
        /* Use type-specific defaults */
        switch (field_type) {
            case 0x0001: field_length = 64; break;
            case 0x0002: field_length = 4; break;
            case 0x0003: field_length = 128; break;
            case 0x0004: field_length = 256; break;
            case 0x0005: field_length = 32; break;
        }
    }

    /* Bounds check: ensure field_length is within packet limits */
    if (field_length > MAX_PACKET_SIZE) {
        fprintf(stderr, "Field length exceeds maximum: %d\n", field_length);
        return -1;
    }

    /* Check we have enough remaining data */
    if ((size_t)field_length > remaining) {
        fprintf(stderr, "Field length %d exceeds remaining data %zu\n",
                field_length, remaining);
        return -1;
    }

    /* Ensure output buffer has space */
    size_t needed = out->used + (size_t)field_length + 8; /* 8 bytes for field header in output */
    if (needed > out->capacity) {
        size_t new_cap = out->capacity * 2;
        while (new_cap < needed) new_cap *= 2;
        char *new_data = realloc(out->data, new_cap);
        if (!new_data) return -1;
        out->data = new_data;
        out->capacity = new_cap;
    }

    /* Write field header to output */
    memcpy(out->data + out->used, desc, sizeof(field_descriptor_t));
    out->used += sizeof(field_descriptor_t);

    /* Copy field data to output buffer */
    if (field_length > 0) {
        memcpy(out->data + out->used, field_data, (size_t)field_length);
        out->used += (size_t)field_length;
    }

    return 0;
}

/*
 * Parse and process all fields in the packet.
 * Returns processed output buffer or NULL on error.
 */
static output_buffer_t *parse_packet_fields(const uint8_t *packet_data,
                                             size_t packet_len,
                                             uint16_t field_count) {
    output_buffer_t *out = create_output_buffer(1024);
    if (!out) return NULL;

    size_t offset = sizeof(packet_header_t);

    for (uint16_t i = 0; i < field_count; i++) {
        /* Ensure we can read the field descriptor */
        if (offset + sizeof(field_descriptor_t) > packet_len) {
            fprintf(stderr, "Truncated field descriptor at index %d\n", i);
            free_output_buffer(out);
            return NULL;
        }

        const field_descriptor_t *desc = (const field_descriptor_t *)(packet_data + offset);
        offset += sizeof(field_descriptor_t);

        size_t remaining = packet_len - offset;

        if (process_field(out, desc, packet_data + offset, remaining) != 0) {
            free_output_buffer(out);
            return NULL;
        }

        int16_t flen = (int16_t)ntohs(desc->field_length);
        if (flen == -1) {
            /* Use same default logic to advance offset */
            uint16_t ft = ntohs(desc->field_type);
            switch (ft) {
                case 0x0001: flen = 64; break;
                case 0x0002: flen = 4; break;
                case 0x0003: flen = 128; break;
                case 0x0004: flen = 256; break;
                case 0x0005: flen = 32; break;
                default: flen = 0; break;
            }
        }
        if (flen > 0) {
            offset += (size_t)flen;
        }
    }

    return out;
}

static int handle_connection(int client_fd) {
    uint8_t recv_buf[MAX_PACKET_SIZE];
    ssize_t total_read = 0;

    /* Read packet header first */
    ssize_t n = read(client_fd, recv_buf, sizeof(packet_header_t));
    if (n < (ssize_t)sizeof(packet_header_t)) {
        fprintf(stderr, "Failed to read header\n");
        return -1;
    }
    total_read = n;

    packet_header_t *hdr = (packet_header_t *)recv_buf;

    if (validate_header(hdr) != 0) {
        return -1;
    }

    uint32_t total_len = ntohl(hdr->total_length);

    /* Verify checksum field */
    uint32_t stated_checksum = ntohl(hdr->checksum);

    /* Read remaining packet data */
    size_t to_read = total_len - sizeof(packet_header_t);
    while ((size_t)total_read < total_len) {
        n = read(client_fd, recv_buf + total_read, to_read - (total_read - sizeof(packet_header_t)));
        if (n <= 0) {
            fprintf(stderr, "Connection closed during read\n");
            return -1;
        }
        total_read += n;
    }

    /* Verify checksum over payload (excluding checksum field itself) */
    uint32_t computed = compute_checksum(recv_buf + sizeof(packet_header_t),
                                          total_len - sizeof(packet_header_t));
    if (computed != stated_checksum) {
        fprintf(stderr, "Checksum mismatch: expected 0x%08x, got 0x%08x\n",
                stated_checksum, computed);
        return -1;
    }

    uint16_t field_count = ntohs(hdr->field_count);

    output_buffer_t *result = parse_packet_fields(recv_buf, total_len, field_count);
    if (!result) {
        return -1;
    }

    /* Send processed result back */
    write(client_fd, result->data, result->used);
    free_output_buffer(result);

    return 0;
}

int main(int argc, char *argv[]) {
    int port = 8443;
    if (argc > 1) port = atoi(argv[1]);

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) { perror("socket"); return 1; }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = htons(port);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind"); close(server_fd); return 1;
    }

    if (listen(server_fd, 5) < 0) {
        perror("listen"); close(server_fd); return 1;
    }

    printf("Listening on 127.0.0.1:%d\n", port);

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) { perror("accept"); continue; }

        handle_connection(client_fd);
        close(client_fd);
    }

    close(server_fd);
    return 0;
}
